/**
 * Generates the local self-signed certificate the API uses for HTTPS:
 * certs/key.pem and certs/cert.pem (valid for 365 days, CN=localhost).
 *
 * Works the same on Windows, macOS and Linux. OpenSSL is called directly
 * with an argument list (no shell), so Git Bash can't rewrite the
 * "/C=ZA/..." subject into a Windows path, and on Windows the OpenSSL that
 * ships with Git is used if openssl isn't on the PATH.
 *
 * Refuses to overwrite existing certs unless run with --force.
 *
 * Usage (from api/): npm run certs
 */
const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const logger = require('../src/utils/logger');

const CERT_DIR = path.join(__dirname, '..', 'certs');
const KEY_PATH = path.join(CERT_DIR, 'key.pem');
const CERT_PATH = path.join(CERT_DIR, 'cert.pem');
const SUBJECT = '/C=ZA/ST=Gauteng/L=Johannesburg/O=NullDevs/OU=INSY7314/CN=localhost';

// OpenSSL that ships with Git for Windows, for when it isn't on the PATH.
const WINDOWS_FALLBACKS = [
  'C:\\Program Files\\Git\\usr\\bin\\openssl.exe',
  'C:\\Program Files\\Git\\mingw64\\bin\\openssl.exe',
  'C:\\Program Files (x86)\\Git\\usr\\bin\\openssl.exe',
];

function findOpenssl() {
  const onPath = spawnSync('openssl', ['version'], { encoding: 'utf8' });
  if (onPath.status === 0) return 'openssl';
  if (process.platform === 'win32') {
    return WINDOWS_FALLBACKS.find((candidate) => fs.existsSync(candidate)) || null;
  }
  return null;
}

function main() {
  const force = process.argv.includes('--force');
  if (!force && fs.existsSync(KEY_PATH) && fs.existsSync(CERT_PATH)) {
    logger.info('certs/key.pem and certs/cert.pem already exist - nothing to do (use --force to replace them)');
    return 0;
  }

  const openssl = findOpenssl();
  if (!openssl) {
    logger.error('OpenSSL not found. Install it (or Git for Windows, which includes it) and try again.');
    return 1;
  }

  fs.mkdirSync(CERT_DIR, { recursive: true });
  const result = spawnSync(
    openssl,
    ['req', '-x509', '-newkey', 'rsa:2048', '-keyout', KEY_PATH, '-out', CERT_PATH, '-days', '365', '-nodes', '-subj', SUBJECT],
    { encoding: 'utf8' }
  );

  if (result.status !== 0 || !fs.existsSync(KEY_PATH) || !fs.existsSync(CERT_PATH)) {
    logger.error('OpenSSL could not create the certificate', { exitCode: result.status });
    return 1;
  }

  logger.info('Created certs/key.pem and certs/cert.pem (self-signed, CN=localhost, 365 days)');
  return 0;
}

process.exitCode = main();

/**
 * Starts the API with relaxed rate limits for the main Newman run, which
 * registers and logs in far more often than the strict limits allow.
 *
 * Only for local testing. It refuses to run with NODE_ENV=production, and
 * the API ignores these overrides in production anyway.
 *
 * Usage (from api/): npm run start:test
 */
const logger = require('../src/utils/logger');

const RELAXED_MAX = '10000';
const OVERRIDES = [
  'RATE_LIMIT_LOGIN_MAX',
  'RATE_LIMIT_REGISTER_MAX',
  'RATE_LIMIT_BOOKING_MAX',
  'RATE_LIMIT_GENERAL_MAX',
];

if (process.env.NODE_ENV === 'production') {
  logger.error('start:test refuses to run when NODE_ENV is production');
  process.exit(1);
}

// Set before the server loads .env - dotenv never overwrites a variable
// that's already set, so these win over anything in the file.
for (const key of OVERRIDES) {
  process.env[key] = RELAXED_MAX;
}
logger.warn('Starting with RELAXED rate limits - for local testing only');

require('../src/server');

/**
 * Rate limit settings.
 *
 * The strict values below are the real limits. For local testing the max
 * of each limiter can be raised with an env variable (the main Newman run
 * registers and logs in far more often than a real user would), but those
 * overrides are IGNORED when NODE_ENV is production, so the strict values
 * can't be relaxed in a deployed API by mistake.
 */
const MINUTE = 60 * 1000;

const STRICT_LIMITS = {
  // Failed logins only - successful ones don't count.
  login: { windowMs: 15 * MINUTE, max: 5, envKey: 'RATE_LIMIT_LOGIN_MAX' },
  register: { windowMs: 60 * MINUTE, max: 10, envKey: 'RATE_LIMIT_REGISTER_MAX' },
  // Per authenticated user, not per IP.
  booking: { windowMs: 10 * MINUTE, max: 10, envKey: 'RATE_LIMIT_BOOKING_MAX' },
  // Safety net across the whole API.
  general: { windowMs: 15 * MINUTE, max: 100, envKey: 'RATE_LIMIT_GENERAL_MAX' },
};

function resolveRateLimits(env = process.env) {
  const isProduction = env.NODE_ENV === 'production';
  const limits = {};
  const ignoredOverrides = [];

  for (const [name, { windowMs, max, envKey }] of Object.entries(STRICT_LIMITS)) {
    const override = Number.parseInt(env[envKey], 10);
    const hasOverride = env[envKey] !== undefined && Number.isInteger(override) && override > 0;

    if (hasOverride && isProduction) ignoredOverrides.push(envKey);
    limits[name] = { windowMs, max: hasOverride && !isProduction ? override : max };
  }

  return { limits, ignoredOverrides };
}

module.exports = { STRICT_LIMITS, resolveRateLimits };

const Gig = require('../models/Gig');
const { AppError } = require('../middleware/errorHandler');
const escapeRegex = require('../utils/escapeRegex');
const { removeOrDeactivateGig } = require('../utils/gigRemoval');
const logger = require('../utils/logger');

// Fields a freelancer may set. The owner (freelancer) is never in these
// lists - it always comes from req.user.id.
const CREATE_FIELDS = ['title', 'description', 'price', 'category', 'deliveryDays'];
const UPDATE_FIELDS = [...CREATE_FIELDS, 'isActive'];

// Only the freelancer's name is shown on a gig - never their email.
const FREELANCER_PUBLIC_FIELDS = 'name';

const DEFAULT_PAGE_SIZE = 10;

function pick(source, fields) {
  const picked = {};
  for (const field of fields) {
    if (source[field] !== undefined) picked[field] = source[field];
  }
  return picked;
}

// GET /api/gigs - active gigs, newest first, with filters and pagination.
async function listGigs(req, res, next) {
  try {
    const page = req.query.page || 1;
    const limit = req.query.limit || DEFAULT_PAGE_SIZE;
    const { category, q, minPrice, maxPrice } = req.query;

    const filter = { isActive: true };
    if (category) filter.category = category;
    if (minPrice !== undefined || maxPrice !== undefined) {
      filter.price = {};
      if (minPrice !== undefined) filter.price.$gte = minPrice;
      if (maxPrice !== undefined) filter.price.$lte = maxPrice;
    }
    if (q) {
      // Escaped so the search is plain text, not a user-supplied pattern.
      const pattern = new RegExp(escapeRegex(q), 'i');
      filter.$or = [{ title: pattern }, { description: pattern }];
    }

    const [gigs, total] = await Promise.all([
      Gig.find(filter)
        .sort({ createdAt: -1 })
        .skip((page - 1) * limit)
        .limit(limit)
        .populate('freelancer', FREELANCER_PUBLIC_FIELDS),
      Gig.countDocuments(filter),
    ]);

    res.status(200).json({
      success: true,
      data: { gigs: gigs.map((g) => g.toJSON()), page, limit, total },
    });
  } catch (err) {
    next(err);
  }
}

// GET /api/gigs/mine - the logged-in freelancer's gigs, including inactive ones.
async function listMyGigs(req, res, next) {
  try {
    const gigs = await Gig.find({ freelancer: req.user.id }).sort({ createdAt: -1 });

    res.status(200).json({
      success: true,
      data: { gigs: gigs.map((g) => g.toJSON()) },
    });
  } catch (err) {
    next(err);
  }
}

// GET /api/gigs/:id - one gig. Inactive gigs are only visible to their owner;
// everyone else gets the same 404 as a gig that doesn't exist.
async function getGig(req, res, next) {
  try {
    const gig = await Gig.findById(req.params.id).populate('freelancer', FREELANCER_PUBLIC_FIELDS);

    const isOwner = Boolean(gig && gig.freelancer && gig.freelancer.id === req.user.id);
    if (!gig || (!gig.isActive && !isOwner)) {
      throw new AppError('Gig not found', 404);
    }

    res.status(200).json({ success: true, data: { gig: gig.toJSON() } });
  } catch (err) {
    next(err);
  }
}

// POST /api/gigs - freelancer only. The owner is always the logged-in user.
async function createGig(req, res, next) {
  try {
    const gig = await Gig.create({
      ...pick(req.body, CREATE_FIELDS),
      freelancer: req.user.id,
    });

    logger.event('GIG', 'Gig created', { gigId: gig.id, freelancerId: req.user.id });

    res.status(201).json({ success: true, data: { gig: gig.toJSON() } });
  } catch (err) {
    next(err);
  }
}

// PUT /api/gigs/:id - owner only. requireOwnership has already loaded the
// gig into req.resource and checked it belongs to req.user.
async function updateGig(req, res, next) {
  try {
    const gig = req.resource;
    const updates = pick(req.body, UPDATE_FIELDS);

    Object.assign(gig, updates);
    await gig.save();

    logger.event('GIG', 'Gig updated', {
      gigId: gig.id,
      freelancerId: req.user.id,
      fields: Object.keys(updates),
    });

    res.status(200).json({ success: true, data: { gig: gig.toJSON() } });
  } catch (err) {
    next(err);
  }
}

// DELETE /api/gigs/:id - owner only. A gig with bookings is deactivated
// instead of deleted, so bookings and transactions keep a valid reference.
async function deleteGig(req, res, next) {
  try {
    const result = await removeOrDeactivateGig(req.resource);

    logger.event('GIG', result.deleted ? 'Gig deleted' : 'Gig deactivated instead of deleted - it has bookings', {
      gigId: result.id,
      freelancerId: req.user.id,
    });

    res.status(200).json({ success: true, data: result });
  } catch (err) {
    next(err);
  }
}

module.exports = { listGigs, listMyGigs, getGig, createGig, updateGig, deleteGig };

const jwt = require('jsonwebtoken');
const mongoose = require('mongoose');
const { AppError } = require('./errorHandler');
const User = require('../models/User');
const logger = require('../utils/logger');

/**
 * Protects a route - requires a valid JWT in the Authorization header
 * as: "Authorization: Bearer <token>"
 *
 * On success, attaches the authenticated user to req.user so downstream
 * controllers can use it (e.g. req.user.id, req.user.role).
 */
async function protect(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return next(new AppError('Not authenticated - no token provided', 401));
  }

  const token = authHeader.split(' ')[1];

  let decoded;
  try {
    decoded = jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    // Covers both expired and tampered/invalid tokens - same generic
    // message either way, no need to tell an attacker which case it was.
    return next(new AppError('Not authenticated - invalid or expired token', 401));
  }

  if (!mongoose.isValidObjectId(decoded.id)) {
    return next(new AppError('Not authenticated - invalid or expired token', 401));
  }

  try {
    // Role comes from the database, not the token, so a role change takes
    // effect straight away.
    const user = await User.findById(decoded.id).select('role');

    if (!user) {
      return next(new AppError('Not authenticated - user no longer exists', 401));
    }

    req.user = { id: user.id, role: user.role };
    next();
  } catch (err) {
    // A database failure is a server error, not an auth failure.
    next(err);
  }
}

/**
 * Role-based access control - use after `protect`.
 * Usage: router.delete('/gigs/:id', protect, requireRole('freelancer'), ...)
 *
 * The response stays generic - it never says which roles would have been
 * allowed, so it can't be used to map out the permission model.
 */
function requireRole(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      logger.event('RBAC', 'Access denied - wrong role', {
        userId: req.user ? req.user.id : null,
        role: req.user ? req.user.role : null,
        method: req.method,
        path: req.originalUrl,
      });
      return next(new AppError('You do not have permission to perform this action', 403));
    }
    next();
  };
}

module.exports = { protect, requireRole };

const logger = require('../utils/logger');

/**
 * Custom error class so controllers can throw errors with a specific
 * HTTP status code attached, e.g:
 *   throw new AppError('Email already registered', 409);
 */
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // distinguishes "expected" errors from bugs
  }
}

// body-parser error types -> [safe message, status].
const BODY_PARSER_MESSAGES = {
  'entity.parse.failed': ['Request body is not valid JSON', 400],
  'entity.too.large': ['Request body is too large', 413],
  'entity.verify.failed': ['Request body could not be read', 400],
  'request.aborted': ['Request was aborted', 400],
  'request.size.invalid': ['Request body could not be read', 400],
  'stream.encoding.set': ['Request body could not be read', 400],
  'charset.unsupported': ['Unsupported character set', 415],
  'encoding.unsupported': ['Unsupported content encoding', 415],
  'parameters.too.many': ['Too many parameters in request body', 413],
};

/**
 * 404 handler - for any route that doesn't match.
 * Must be registered AFTER all real routes, BEFORE the error handler.
 */
function notFoundHandler(req, res, next) {
  // req.path, not originalUrl: the query string is never echoed back.
  next(new AppError(`Route not found: ${req.method} ${req.path}`, 404));
}

/**
 * Centralised error handler - must be the LAST middleware registered.
 *
 * Rubric requirement: error responses must never expose stack traces,
 * file paths, or config values. This is the one place that formats every
 * error response, so nobody accidentally leaks internals from inside a
 * controller.
 *
 * Validation-specific error shaping (e.g. field-level messages from
 * express-validator) plugs in here too - Lihle extends this file with
 * that logic rather than creating a second error handler.
 */
function errorHandler(err, req, res, next) {
  // Mongoose rejected the data (schema validation, bad cast, unknown field
  // under strict: 'throw'). That's bad input, not a server fault, but the
  // raw message names schema paths, so it's replaced with a generic one.
  if (['ValidationError', 'CastError', 'StrictModeError'].includes(err.name)) {
    err = Object.assign(new AppError('Invalid input', 400), { stack: err.stack, cause: err.message });
  }

  // The body parser rejected the request before any route ran (bad JSON,
  // too large, unsupported encoding). Its own messages can quote the raw
  // body, so they're swapped for fixed ones.
  if (err.type && BODY_PARSER_MESSAGES[err.type]) {
    const [message, status] = BODY_PARSER_MESSAGES[err.type];
    err = Object.assign(new AppError(message, status), { stack: err.stack, cause: err.type });
  }

  // CORS refused a disallowed browser origin (see config/security.js).
  if (err.blockedOrigin) {
    logger.event('CORS', 'Blocked request from a disallowed origin', {
      origin: err.blockedOrigin,
      method: req.method,
      path: req.originalUrl,
      ip: req.ip,
    });
  }

  const statusCode = err.statusCode || 500;

  // Full details go to the server log only - never to the client. Stack
  // traces are only logged for unexpected errors (bugs), and never in
  // production; expected ones (bad input, 401/403/404) don't need them.
  const logStack = !err.isOperational && process.env.NODE_ENV !== 'production';
  logger.error(err.message, {
    statusCode,
    path: req.originalUrl,
    method: req.method,
    cause: err.cause,
    stack: logStack ? err.stack : undefined,
  });

  const safeMessage =
    err.isOperational && err.message
      ? err.message
      : 'Something went wrong. Please try again later.';

  res.status(statusCode).json({
    success: false,
    error: safeMessage,
  });
}

module.exports = { AppError, notFoundHandler, errorHandler };

const { body, query, checkExact } = require('express-validator');
const { GIG_CATEGORIES } = require('../models/Gig');

/**
 * Validation for the gig routes. Text fields are trimmed, length-checked
 * and then HTML-escaped, so markup typed into a gig can't run in anyone's
 * browser later.
 *
 * Type checks use typeof on purpose: express-validator's built-in
 * validators check each item of an array separately, so isString() alone
 * would let ["a", "b"] through.
 *
 * Unknown fields are rejected outright (checkExact), so fields like
 * "freelancer" or "isActive" can't be slipped into a create request.
 */

const MAX_PRICE = 100000;
const UNKNOWN_FIELDS_MESSAGE = 'Request contains fields that are not allowed';

const isText = (value) => typeof value === 'string';
const isNumber = (value) => typeof value === 'number' && Number.isFinite(value);
const hasAtMostTwoDecimals = (value) => /^\d+(\.\d{1,2})?$/.test(String(value));

// Builds the field rules shared by create (all required) and update (all optional).
function gigFieldRules({ optional }) {
  const field = (name, label) => {
    const chain = body(name);
    return optional ? chain.optional() : chain.exists().withMessage(`${label} is required`).bail();
  };

  return [
    field('title', 'Title')
      .custom(isText).withMessage('Title must be text').bail()
      .trim()
      .isLength({ min: 3, max: 100 }).withMessage('Title must be 3-100 characters')
      .escape(),
    field('description', 'Description')
      .custom(isText).withMessage('Description must be text').bail()
      .trim()
      .isLength({ min: 10, max: 1000 }).withMessage('Description must be 10-1000 characters')
      .escape(),
    field('price', 'Price')
      .custom(isNumber).withMessage('Price must be a number').bail()
      .custom((value) => value >= 1 && value <= MAX_PRICE)
      .withMessage(`Price must be between 1 and ${MAX_PRICE}`).bail()
      .custom(hasAtMostTwoDecimals).withMessage('Price can have at most 2 decimal places'),
    field('category', 'Category')
      .custom(isText).withMessage('Category must be text').bail()
      .trim()
      .isIn(GIG_CATEGORIES).withMessage(`Category must be one of: ${GIG_CATEGORIES.join(', ')}`)
      .escape(),
    field('deliveryDays', 'Delivery days')
      .custom((value) => Number.isInteger(value) && value >= 1 && value <= 90)
      .withMessage('Delivery days must be a whole number from 1 to 90'),
  ];
}

const createGigRules = [
  checkExact(gigFieldRules({ optional: false }), {
    locations: ['body'],
    message: UNKNOWN_FIELDS_MESSAGE,
  }),
];

const updateGigRules = [
  checkExact(
    [
      ...gigFieldRules({ optional: true }),
      body('isActive')
        .optional()
        .custom((value) => typeof value === 'boolean').withMessage('isActive must be true or false'),
    ],
    { locations: ['body'], message: UNKNOWN_FIELDS_MESSAGE }
  ),
  // Kept outside checkExact: a whole-body rule there would count every
  // field as "known" and switch the unknown-field check off.
  body()
    .custom((value) => value && typeof value === 'object' && Object.keys(value).length > 0)
    .withMessage('Provide at least one field to update'),
];

// Query strings arrive as strings - but ?q=a&q=b arrives as an array, so
// every param is checked for a single value first.
const singleQuery = (name) =>
  query(name)
    .optional()
    .custom(isText).withMessage(`${name} must be a single value`).bail();

const listGigsQueryRules = [
  checkExact(
    [
      singleQuery('page').isInt({ min: 1, max: 1000 }).withMessage('page must be a whole number from 1 to 1000').toInt(),
      singleQuery('limit').isInt({ min: 1, max: 50 }).withMessage('limit must be a whole number from 1 to 50').toInt(),
      singleQuery('category').isIn(GIG_CATEGORIES).withMessage(`category must be one of: ${GIG_CATEGORIES.join(', ')}`),
      // Escaped like the stored text, so a search for "Tom & Jerry" matches
      // what's actually saved ("Tom &amp; Jerry").
      singleQuery('q').trim().isLength({ max: 50 }).withMessage('q can be at most 50 characters').escape(),
      singleQuery('minPrice').isFloat({ min: 0, max: MAX_PRICE }).withMessage('minPrice must be a number from 0 to 100000').toFloat(),
      singleQuery('maxPrice').isFloat({ min: 0, max: MAX_PRICE }).withMessage('maxPrice must be a number from 0 to 100000').toFloat(),
      query('maxPrice')
        .optional()
        .custom((max, { req }) => req.query.minPrice === undefined || Number(req.query.minPrice) <= Number(max))
        .withMessage('minPrice cannot be greater than maxPrice'),
    ],
    { locations: ['query'], message: 'Request contains query parameters that are not allowed' }
  ),
];

module.exports = {
  createGigRules,
  updateGigRules,
  listGigsQueryRules,
};

const { AppError } = require('./errorHandler');
const logger = require('../utils/logger');

/**
 * Loads the document for req.params.id and checks the logged-in user owns it.
 * Use after `protect` and `validateObjectId`.
 *
 * Usage:
 *   router.put('/:id', protect, validateObjectId,
 *     requireOwnership(Gig, { ownerField: 'freelancer', resourceName: 'Gig' }),
 *     updateGig);
 *
 * Options:
 *   ownerField   - field on the document holding the owner's user id, or an
 *                  array of fields when a record has more than one owner
 *                  (a booking belongs to both its client and its freelancer)
 *   resourceName - used in the 404 message ("Gig not found")
 *   allowAdmin   - when true, admins skip the owner check
 *
 * The owner is always compared against req.user.id, which comes from the
 * verified token plus a database lookup in `protect` - never from the body
 * or query string. On success the document is attached to req.resource so
 * the controller doesn't have to query it again.
 */
function requireOwnership(Model, { ownerField, resourceName = 'Resource', allowAdmin = false }) {
  const ownerFields = [].concat(ownerField || []);
  if (ownerFields.length === 0) {
    throw new Error('requireOwnership needs an ownerField');
  }

  return async (req, res, next) => {
    try {
      const doc = await Model.findById(req.params.id);

      if (!doc) {
        throw new AppError(`${resourceName} not found`, 404);
      }

      const isAdminBypass = allowAdmin && req.user.role === 'admin';
      const isOwner = ownerFields.some(
        (field) => doc[field] && doc[field].toString() === String(req.user.id)
      );

      if (!isAdminBypass && !isOwner) {
        logger.event('RBAC', 'Access denied - not the owner', {
          userId: req.user.id,
          role: req.user.role,
          resource: resourceName,
          resourceId: req.params.id,
          method: req.method,
          path: req.originalUrl,
        });
        throw new AppError('You do not have permission to perform this action', 403);
      }

      req.resource = doc;
      next();
    } catch (err) {
      next(err);
    }
  };
}

module.exports = { requireOwnership };

const {
  TAX_TABLES,
  SUPPORTED_TAX_YEARS,
  TAX_ASSUMPTIONS,
  TAX_DISCLAIMER,
  SOURCE_URL,
  CHECKED_ON,
} = require('../config/tax');
const { calculateIncomeTax } = require('./taxCalculator');
const { getTaxYearRange, taxYearForDate } = require('./taxYear');

/**
 * Pure helpers behind GET /api/income/tax-estimate, kept out of the
 * controller so they can be unit tested without a database.
 */

// The tax year containing `now`. If SARS tables for it haven't been added
// to config/tax.js yet (e.g. just after 1 March), falls back to the newest
// configured year rather than guessing new rates.
function defaultTaxYear(now = new Date()) {
  const current = taxYearForDate(now);
  return TAX_TABLES[current] ? current : SUPPORTED_TAX_YEARS[0];
}

/**
 * @param {number} startYear tax year start, must be in TAX_TABLES
 * @param {Array<{ month: string, incomeCents: number, bookings: number }>} monthlyRows
 *   one row per month that had income ("YYYY-MM"), amounts in whole cents
 */
function buildTaxEstimate(startYear, monthlyRows = []) {
  const table = TAX_TABLES[startYear];
  if (!table) throw new RangeError(`No tax table configured for ${startYear}`);

  const range = getTaxYearRange(startYear);
  const byMonth = new Map(monthlyRows.map((row) => [row.month, row]));

  // Every month of the tax year, March to February, zeros included.
  // Rows outside the tax year are ignored.
  let grossCents = 0;
  const monthly = range.months.map((month) => {
    const row = byMonth.get(month);
    const incomeCents = row ? row.incomeCents : 0;
    grossCents += incomeCents;
    return { month, income: incomeCents / 100, bookings: row ? row.bookings : 0 };
  });

  const result = calculateIncomeTax(grossCents / 100, table);

  return {
    taxYear: { label: range.label, start: range.start, end: range.end },
    totals: {
      gross: result.gross,
      taxBeforeRebate: result.taxBeforeRebate,
      estimatedTax: result.estimatedTax,
      takeHome: result.takeHome,
      effectiveRatePercent: result.effectiveRatePercent,
    },
    rebate: result.rebate,
    taxFreeThreshold: table.taxFreeThreshold,
    breakdown: result.breakdown,
    monthly,
    assumptions: [...TAX_ASSUMPTIONS],
    disclaimer: TAX_DISCLAIMER,
    source: { name: 'SARS - Rates of Tax for Individuals', url: SOURCE_URL, checkedOn: CHECKED_ON },
    availableTaxYears: [...SUPPORTED_TAX_YEARS],
  };
}

module.exports = { defaultTaxYear, buildTaxEstimate };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { TAX_TABLES, SUPPORTED_TAX_YEARS } = require('../src/config/tax');
const { calculateIncomeTax } = require('../src/utils/taxCalculator');

// Guards against typos when the tables are updated each year.
for (const year of SUPPORTED_TAX_YEARS) {
  test(`tax table for the year starting March ${year} is consistent`, () => {
    const table = TAX_TABLES[year];
    assert.equal(table.sarsTaxYear, year + 1, 'SARS names the year after the year it ends in');

    table.brackets.forEach((bracket, i) => {
      if (i > 0) assert.equal(bracket.from, table.brackets[i - 1].to, 'brackets must be contiguous');
      // Tax at the bottom of each bracket must equal the base amount SARS prints.
      assert.equal(calculateIncomeTax(bracket.from, table).taxBeforeRebate, bracket.baseTax);
    });
    assert.equal(table.brackets[0].from, 0);
    assert.equal(table.brackets[table.brackets.length - 1].to, null);

    // At the threshold, tax before rebate equals the rebate exactly.
    assert.equal(calculateIncomeTax(table.taxFreeThreshold, table).taxBeforeRebate, table.primaryRebate);
  });
}

test('supported years are listed newest first', () => {
  assert.deepEqual(SUPPORTED_TAX_YEARS, [2026, 2025, 2024, 2023]);
});

test('tax tables cannot be changed at runtime', () => {
  assert.ok(Object.isFrozen(TAX_TABLES));
  assert.ok(Object.isFrozen(TAX_TABLES[2026].brackets[0]));
  assert.ok(Object.isFrozen(TAX_TABLES[2023].brackets));
});
